std::string BitfieldName_MapBufferAccessMask(GLbitfield value) {
    std::string out;
    GLbitfield rest = value;
    if (value & 0x1u) { if (!out.empty()) out += " | "; out += "GL_MAP_READ_BIT"; rest &= ~0x1u; }
    if (value & 0x2u) { if (!out.empty()) out += " | "; out += "GL_MAP_WRITE_BIT"; rest &= ~0x2u; }
    if (value & 0x4u) { if (!out.empty()) out += " | "; out += "GL_MAP_INVALIDATE_RANGE_BIT"; rest &= ~0x4u; }
    if (value & 0x8u) { if (!out.empty()) out += " | "; out += "GL_MAP_INVALIDATE_BUFFER_BIT"; rest &= ~0x8u; }
    if (value & 0x10u) { if (!out.empty()) out += " | "; out += "GL_MAP_FLUSH_EXPLICIT_BIT"; rest &= ~0x10u; }
    if (value & 0x20u) { if (!out.empty()) out += " | "; out += "GL_MAP_UNSYNCHRONIZED_BIT"; rest &= ~0x20u; }
    if (value & 0x40u) { if (!out.empty()) out += " | "; out += "GL_MAP_PERSISTENT_BIT_EXT"; rest &= ~0x40u; }
    if (value & 0x80u) { if (!out.empty()) out += " | "; out += "GL_MAP_COHERENT_BIT_EXT"; rest &= ~0x80u; }
    if (value & 0x4000u) { if (!out.empty()) out += " | "; out += "GL_MAP_CLIENT_POINTER_BIT_MESA"; rest &= ~0x4000u; }
    if (rest || out.empty()) { if (!out.empty()) out += " | "; char buf[16]; snprintf(buf, sizeof(buf), "0x%X", rest); out += buf; }
    return out;
}

