std::string BitfieldName_SyncObjectMask(GLbitfield value) {
    std::string out;
    GLbitfield rest = value;
    if (value & 0x1u) { if (!out.empty()) out += " | "; out += "GL_SYNC_FLUSH_COMMANDS_BIT"; rest &= ~0x1u; }
    if (rest || out.empty()) { if (!out.empty()) out += " | "; char buf[16]; snprintf(buf, sizeof(buf), "0x%X", rest); out += buf; }
    return out;
}

