std::string BitfieldName_UseProgramStageMask(GLbitfield value) {
    std::string out;
    GLbitfield rest = value;
    if (value & 0x1u) { if (!out.empty()) out += " | "; out += "GL_VERTEX_SHADER_BIT"; rest &= ~0x1u; }
    if (value & 0x2u) { if (!out.empty()) out += " | "; out += "GL_FRAGMENT_SHADER_BIT"; rest &= ~0x2u; }
    if (value & 0x4u) { if (!out.empty()) out += " | "; out += "GL_GEOMETRY_SHADER_BIT"; rest &= ~0x4u; }
    if (value & 0x8u) { if (!out.empty()) out += " | "; out += "GL_TESS_CONTROL_SHADER_BIT"; rest &= ~0x8u; }
    if (value & 0x10u) { if (!out.empty()) out += " | "; out += "GL_TESS_EVALUATION_SHADER_BIT"; rest &= ~0x10u; }
    if (value & 0x20u) { if (!out.empty()) out += " | "; out += "GL_COMPUTE_SHADER_BIT"; rest &= ~0x20u; }
    if (value & 0x40u) { if (!out.empty()) out += " | "; out += "GL_MESH_SHADER_BIT_EXT"; rest &= ~0x40u; }
    if (value & 0x80u) { if (!out.empty()) out += " | "; out += "GL_TASK_SHADER_BIT_EXT"; rest &= ~0x80u; }
    if (rest || out.empty()) { if (!out.empty()) out += " | "; char buf[16]; snprintf(buf, sizeof(buf), "0x%X", rest); out += buf; }
    return out;
}

